// ===== GENERATE PLACEHOLDER IMAGES (SVG-based) =====
function generateProductImage(product, index) {
  const colors = product.colors || ["#1a1a2e", "#00d4aa", "#f5f5f7"];
  const hue = (product.id * 60 + index * 30) % 360;
  return `data:image/svg+xml,${encodeURIComponent(`
    <svg xmlns="http://www.w3.org/2000/svg" width="600" height="400" viewBox="0 0 600 400">
      <defs>
        <linearGradient id="g" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" style="stop-color:hsl(${hue},60%,12%)"/>
          <stop offset="100%" style="stop-color:hsl(${hue + 40},70%,18%)"/>
        </linearGradient>
        <radialGradient id="glow" cx="50%" cy="40%">
          <stop offset="0%" style="stop-color:hsl(${hue + 20},80%,50%);stop-opacity:0.3"/>
          <stop offset="100%" style="stop-color:transparent"/>
        </radialGradient>
      </defs>
      <rect width="600" height="400" fill="url(#g)"/>
      <circle cx="300" cy="180" r="120" fill="url(#glow)"/>
      <rect x="220" y="130" width="160" height="100" rx="16" fill="hsl(${hue + 20},60%,30%)" opacity="0.6"/>
      <circle cx="300" cy="180" r="30" fill="hsl(${hue},80%,60%)" opacity="0.8"/>
      <text x="300" y="340" text-anchor="middle" font-family="Inter,sans-serif" font-size="14" fill="rgba(255,255,255,0.3)">${product.name}</text>
    </svg>
  `)}`;
}

// ===== RENDER PRODUCTS =====
function renderProducts() {
  const grid = document.getElementById("productsGrid");
  grid.innerHTML = products.map((p, idx) => {
    // Build media slides: images + video
    let slides = [];
    if (p.images && p.images.length > 0) {
      p.images.forEach((src, i) => {
        slides.push(`<img src="${src}" alt="${p.name} - photo ${i+1}" class="product-slide ${i === 0 ? 'active' : ''}" data-idx="${slides.length}">`);
      });
    } else {
      const img1 = p.img1 || generateProductImage(p, 0);
      const img2 = p.img2 || generateProductImage(p, 1);
      slides.push(`<img src="${img1}" alt="${p.name}" class="product-slide active" data-idx="0">`);
      slides.push(`<img src="${img2}" alt="${p.name} vue 2" class="product-slide" data-idx="1">`);
    }
    if (p.video) {
      slides.push(`<video src="${p.video}" class="product-slide" data-idx="${slides.length}" muted loop playsinline></video>`);
    }
    const dotsHTML = slides.map((_, i) => `<span class="media-dot ${i === 0 ? 'active' : ''}" data-slide="${i}"></span>`).join('');
    const waMsg = encodeURIComponent(`Bonjour! Je suis intéressé(e) par: ${p.name} (${p.price} MAD). Est-il disponible?`);
    return `
      <div class="product-card reveal nano-float" style="animation-delay: ${idx * 0.15}s">
        <a href="product.html?id=${p.id}" class="product-media" style="display:block;">
          <span class="product-badge">${p.badge}</span>
          ${slides.join('\n          ')}
          <div class="media-nav" onclick="event.preventDefault(); event.stopPropagation();">
            ${dotsHTML}
          </div>
        </a>
        <div class="product-info">
          <a href="product.html?id=${p.id}"><h3 class="product-name">${p.name}</h3></a>
          <p class="product-desc">${p.desc}</p>
          <div class="product-price-row">
            <span class="product-price">${p.price} MAD</span>
            <span class="product-old-price">${p.oldPrice} MAD</span>
          </div>
          <a href="https://wa.me/${WHATSAPP_NUMBER}?text=${waMsg}" target="_blank" class="btn-whatsapp magnetic-btn">
            ${whatsappSVG}
            Commander via WhatsApp
          </a>
        </div>
      </div>
    `;
  }).join("");

  // Product media slider with swipe support
  document.querySelectorAll(".product-card").forEach(card => {
    const slides = card.querySelectorAll(".product-slide");
    const dots = card.querySelectorAll(".media-dot");
    let current = 0;

    function goToSlide(idx) {
      slides.forEach(s => { s.style.display = "none"; s.classList.remove("active"); if (s.tagName === "VIDEO") s.pause(); });
      dots.forEach(d => d.classList.remove("active"));
      slides[idx].style.display = "block";
      slides[idx].classList.add("active");
      dots[idx].classList.add("active");
      if (slides[idx].tagName === "VIDEO") { slides[idx].play(); }
      current = idx;
    }

    dots.forEach(dot => {
      dot.addEventListener("click", () => goToSlide(parseInt(dot.dataset.slide)));
    });

    // Swipe support for mobile
    let startX = 0;
    const media = card.querySelector(".product-media");
    media.addEventListener("touchstart", e => { startX = e.touches[0].clientX; }, { passive: true });
    media.addEventListener("touchend", e => {
      const diff = startX - e.changedTouches[0].clientX;
      if (Math.abs(diff) > 40) {
        if (diff > 0 && current < slides.length - 1) goToSlide(current + 1);
        else if (diff < 0 && current > 0) goToSlide(current - 1);
      }
    }, { passive: true });
  });
}

