// ===== NAVBAR SCROLL EFFECT =====
function initNavbar() {
  const navbar = document.getElementById("navbar");
  const toggle = document.getElementById("navToggle");
  const menu = document.getElementById("navMenu");

  window.addEventListener("scroll", () => {
    navbar.classList.toggle("scrolled", window.scrollY > 50);
  });

  toggle.addEventListener("click", () => {
    toggle.classList.toggle("open");
    menu.classList.toggle("open");
  });

  // Close menu on link click
  menu.querySelectorAll("a").forEach(link => {
    link.addEventListener("click", () => {
      toggle.classList.remove("open");
      menu.classList.remove("open");
    });
  });
}

// ===== SCROLL REVEAL (IntersectionObserver) =====
function initReveal() {
  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry, i) => {
      if (entry.isIntersecting) {
        setTimeout(() => {
          entry.target.classList.add("active");
        }, i * 80);
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.1, rootMargin: "0px 0px -50px 0px" });

  document.querySelectorAll(".reveal, .reveal-left, .reveal-scale").forEach(el => {
    observer.observe(el);
  });
}

// ===== COUNTER ANIMATION =====
function initCounters() {
  const counters = document.querySelectorAll("[data-count]");
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const el = entry.target;
        const target = parseInt(el.dataset.count);
        const duration = 2000;
        const start = performance.now();
        
        function update(now) {
          const elapsed = now - start;
          const progress = Math.min(elapsed / duration, 1);
          const eased = 1 - Math.pow(1 - progress, 3);
          el.textContent = Math.floor(target * eased).toLocaleString() + (target < 100 ? "%" : "+");
          if (progress < 1) requestAnimationFrame(update);
        }
        requestAnimationFrame(update);
        observer.unobserve(el);
      }
    });
  }, { threshold: 0.5 });

  counters.forEach(c => observer.observe(c));
}

// ===== NANO BANANA PARALLAX EFFECT =====
function initNanoParallax() {
  let ticking = false;
  window.addEventListener("scroll", () => {
    if (!ticking) {
      requestAnimationFrame(() => {
        const scrollY = window.scrollY;
        // Subtle parallax on product cards
        document.querySelectorAll(".product-card").forEach((card, i) => {
          const rect = card.getBoundingClientRect();
          const centerY = rect.top + rect.height / 2;
          const viewportCenter = window.innerHeight / 2;
          const offset = (centerY - viewportCenter) * 0.02;
          card.style.transform = `translateY(${-offset}px)`;
        });
        // Parallax on hero content
        const heroContent = document.querySelector(".hero-content");
        if (heroContent && scrollY < window.innerHeight) {
          heroContent.style.transform = `translateY(${scrollY * 0.15}px)`;
          heroContent.style.opacity = 1 - scrollY / (window.innerHeight * 0.8);
        }
        ticking = false;
      });
      ticking = true;
    }
  });
}

// ===== MAGNETIC BUTTONS =====
function initMagneticButtons() {
  document.querySelectorAll(".magnetic-btn").forEach(btn => {
    btn.addEventListener("mousemove", (e) => {
      const rect = btn.getBoundingClientRect();
      const x = e.clientX - rect.left - rect.width / 2;
      const y = e.clientY - rect.top - rect.height / 2;
      btn.style.transform = `translate(${x * 0.15}px, ${y * 0.15}px)`;
    });
    btn.addEventListener("mouseleave", () => {
      btn.style.transform = "translate(0, 0)";
    });
  });
}

// ===== SMOOTH ANCHOR SCROLL =====
function initSmoothScroll() {
  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener("click", (e) => {
      e.preventDefault();
      const target = document.querySelector(anchor.getAttribute("href"));
      if (target) {
        const offset = 80;
        const top = target.getBoundingClientRect().top + window.scrollY - offset;
        window.scrollTo({ top, behavior: "smooth" });
      }
    });
  });
}

// ===== CURSOR GLOW EFFECT =====
function initCursorGlow() {
  const glow = document.createElement("div");
  glow.style.cssText = `
    position: fixed; width: 300px; height: 300px; border-radius: 50%;
    background: radial-gradient(circle, rgba(0,212,170,0.04) 0%, transparent 70%);
    pointer-events: none; z-index: 0; transform: translate(-50%, -50%);
    transition: opacity 0.3s;
  `;
  document.body.appendChild(glow);
  
  document.addEventListener("mousemove", (e) => {
    glow.style.left = e.clientX + "px";
    glow.style.top = e.clientY + "px";
  });
}

// ===== RENDER PRODUCT DETAILS (product.html) =====
function renderProductDetails() {
  const container = document.getElementById("productDetailsContainer");
  if (!container) return;
  
  const params = new URLSearchParams(window.location.search);
  const id = parseInt(params.get("id"));
  const p = products.find(prod => prod.id === id);
  
  if (!p) {
    container.innerHTML = `<div style="text-align:center; grid-column:1/-1; padding:100px 0;"><h2>Produit introuvable.</h2><a href="index.html" class="btn-primary" style="margin-top:20px;">Retour à la boutique</a></div>`;
    return;
  }
  
  let mediaHTML = "";
  let thumbsHTML = "";
  
  if (p.images && p.images.length > 0) {
    p.images.forEach((src, i) => {
      mediaHTML += `<img src="${src}" class="main-media-item ${i===0?'active':''}" data-idx="${i}">`;
      thumbsHTML += `<div class="thumbnail ${i===0?'active':''}" data-target="${i}"><img src="${src}"></div>`;
    });
    if (p.video) {
      const idx = p.images.length;
      mediaHTML += `<video src="${p.video}" class="main-media-item" data-idx="${idx}" muted loop playsinline></video>`;
      thumbsHTML += `<div class="thumbnail" data-target="${idx}"><video src="${p.video}" muted></video></div>`;
    }
  } else {
    const img1 = p.img1 || generateProductImage(p, 0);
    const img2 = p.img2 || generateProductImage(p, 1);
    mediaHTML += `<img src="${img1}" class="main-media-item active" data-idx="0">`;
    mediaHTML += `<img src="${img2}" class="main-media-item" data-idx="1">`;
    thumbsHTML += `<div class="thumbnail active" data-target="0"><img src="${img1}"></div>`;
    thumbsHTML += `<div class="thumbnail" data-target="1"><img src="${img2}"></div>`;
  }

  const waMsg = encodeURIComponent(`Bonjour! Je souhaite commander: ${p.name} (${p.price} MAD).`);
  
  container.innerHTML = `
    <div class="product-gallery">
      <div class="main-media-container" id="mainMedia">
        ${mediaHTML}
      </div>
      <div class="thumbnails" id="thumbnails">
        ${thumbsHTML}
      </div>
    </div>
    <div class="product-details reveal">
      <span class="pd-badge">${p.badge}</span>
      <h1 class="pd-title">${p.name}</h1>
      <div class="pd-reviews">
        <span class="pd-stars">★★★★★</span>
        <span>(128 avis vérifiés)</span>
      </div>
      <div class="pd-price-row">
        <span class="pd-price">${p.price} MAD</span>
        <span class="pd-old-price">${p.oldPrice} MAD</span>
      </div>
      <p class="pd-desc">${p.desc}</p>
      
      <div class="pd-features">
        <div class="pd-feature"><div class="pd-feature-icon">🚀</div> Livraison Express partout au Maroc</div>
        <div class="pd-feature"><div class="pd-feature-icon">💰</div> Paiement à la réception</div>
        <div class="pd-feature"><div class="pd-feature-icon">✅</div> Garantie Satisfait ou Remboursé</div>
      </div>
      
      <a href="https://wa.me/${WHATSAPP_NUMBER}?text=${waMsg}" target="_blank" class="btn-whatsapp magnetic-btn pd-cta">
        ${whatsappSVG} Commander Maintenant
      </a>
      
      <div class="pd-urgency">
        <span class="dot"></span> En stock - Plus que quelques articles disponibles!
      </div>
    </div>
  `;
  
  // Gallery logic
  const thumbs = document.querySelectorAll(".thumbnail");
  const mainItems = document.querySelectorAll(".main-media-item");
  thumbs.forEach(t => {
    t.addEventListener("click", () => {
      thumbs.forEach(thumb => thumb.classList.remove("active"));
      mainItems.forEach(item => { item.classList.remove("active"); if (item.tagName === "VIDEO") item.pause(); });
      t.classList.add("active");
      const targetIdx = t.dataset.target;
      const targetItem = document.querySelector(`.main-media-item[data-idx="${targetIdx}"]`);
      if (targetItem) {
        targetItem.classList.add("active");
        if (targetItem.tagName === "VIDEO") targetItem.play();
      }
    });
  });
  initMagneticButtons();
  initReveal();
}

// ===== INIT =====
document.addEventListener("DOMContentLoaded", () => {
  const isProductPage = window.location.pathname.includes("product.html");
  
  initNavbar();
  initSmoothScroll();
  initCursorGlow();
  
  if (isProductPage) {
    renderProductDetails();
  } else {
    const grid = document.getElementById("productsGrid");
    if (grid) {
      renderProducts();
      renderTestimonials();
      initReveal();
      initCounters();
      initNanoParallax();
      initMagneticButtons();
    }
  }
});
